<?php
require_once __DIR__ . '/../config.php';
requireAuth();
$id=(int)query('id',0); $db=getDB();
$stmt=$db->prepare("SELECT g.*, c.name as customer_name, c.phone as customer_phone, c.address as customer_address FROM gold_gives g LEFT JOIN customers c ON c.id=g.customer_id WHERE g.id=? AND g.deleted_at IS NULL"); $stmt->execute([$id]); $give=$stmt->fetch();
if(!$give){ redirect('gold-gives/index.php'); }
$stmt=$db->prepare("SELECT * FROM gold_give_items WHERE give_id=?"); $stmt->execute([$id]); $items=$stmt->fetchAll();
?><!DOCTYPE html><html><head><meta charset="UTF-8"><script>(function(){try{var t=localStorage.getItem('mj_theme')||'dark';document.documentElement.setAttribute('data-theme',t==='light'?'light':'dark')}catch(e){}})();</script><title><?= htmlspecialchars($give['give_no']) ?></title><style>body{font-family:Arial,sans-serif;color:#111}.wrap{max-width:760px;margin:20px auto;border:1px solid #333;padding:24px}.head{display:flex;justify-content:space-between;border-bottom:2px solid #333;padding-bottom:12px;margin-bottom:18px}.title{font-size:24px;font-weight:700}.muted{color:#555;font-size:13px}table{width:100%;border-collapse:collapse;margin-top:16px}th,td{border:1px solid #777;padding:8px;text-align:left}th{background:#f2f2f2}.right{text-align:right}.total{font-weight:700;background:#fafafa}.danger{color:#b91c1c}html[data-theme="light"] .no-print{background:#f8fafc;color:#111827}html[data-theme="dark"] .no-print{background:#0b1120;color:#e8edf5}html[data-theme="dark"] .no-print a{color:#FFD700}@media print{.no-print{display:none}}</style></head><body><div class="no-print" style="text-align:center;margin:10px"><button onclick="window.print()">Print</button> <button type="button" onclick="togglePrintTheme()">Theme</button> <a href="<?= url('gold-gives/show.php?id='.$id) ?>">Back</a></div><div class="wrap"><div class="head"><div><div class="title">M.J Casting</div><div class="muted">Gold Give / Sona Diya</div></div><div style="text-align:right"><strong><?= htmlspecialchars($give['give_no']) ?></strong><br><?= formatDate($give['give_date']) ?></div></div><p><strong>Party:</strong> <?= htmlspecialchars($give['customer_name'] ?? '') ?> &nbsp; <strong>Phone:</strong> <?= htmlspecialchars($give['customer_phone'] ?? '-') ?></p><table><thead><tr><th>Description</th><th class="right">Gross</th><th class="right">Ratti</th><th class="right">Khalis Given</th></tr></thead><tbody><?php foreach($items as $it): ?><tr><td><?= htmlspecialchars($it['description'] ?: '-') ?></td><td class="right"><?= number_format($it['gross_weight'],3) ?></td><td class="right"><?= number_format($it['ratti_impurity'],3) ?></td><td class="right danger"><?= number_format($it['khalis_weight'],3) ?></td></tr><?php endforeach; ?></tbody><tfoot><tr class="total"><td>Total</td><td class="right"><?= number_format($give['total_gross_weight'],3) ?></td><td></td><td class="right danger"><?= number_format($give['total_khalis_weight'],3) ?> g</td></tr></tfoot></table><?php if($give['remarks']): ?><p><strong>Remarks:</strong> <?= htmlspecialchars($give['remarks']) ?></p><?php endif; ?></div><script>function togglePrintTheme(){var t=document.documentElement.getAttribute('data-theme')==='light'?'dark':'light';document.documentElement.setAttribute('data-theme',t);try{localStorage.setItem('mj_theme',t)}catch(e){}}</script></body></html>
